    def __init__(self, target_hash, salt=None, algorithm=\"sha256\", max_length=12):
        self.target_hash = target_hash
        self.salt = salt or b''
        self.algorithm = algorithm
        self.max_length = max_length
        self.common_dict = [\"password\", \"123456\", \"qwerty\", \"admin\", ...]  # 10k+ wordlist

    def dictionary_attack(self):
        for word in self.common_dict:
            mutated = self.mutate_word(word)
            if self.check_hash(mutated):
                return mutated

    def brute_force(self):
        chars = \"abcdefghijklmnopqrstuvwxyz0123456789!@#$\"
        for length in range(1, self.max_length + 1):
            for combo in itertools.product(chars, repeat=length):
                password = \"\".join(combo)
                if self.check_hash(password):
                    return password

    def mutate_word(self, word):
        mutations = [word.upper(), word.capitalize(), word.replace(\"a\", \"@\"), ...]
        yield from mutations

    def check_hash(self, password):
        if self.algorithm == \"sha256\":
            hashed = hashlib.sha256((password + self.salt.decode()).encode()).hexdigest()
        elif self.algorithm == \"pbkdf2\":
            hashed = pbkdf2_sha256.hash(password, salt=self.salt)
        return hashed == self.target_hash

